def lis_length(nums):
    if not nums:
        return 0
    n = len(nums)
    # dp[i] = length of LIS ending at index i
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

# Example: lis_length([10, 9, 2, 5, 3, 7, 101, 18]) returns 4 (2,3,7,101)

