A stack follows last-in-first-out order where the most recently added element is removed first, while a queue follows first-in-first-out order where the oldest element is removed first. Stacks support push and pop operations at the same end, whereas queues enqueue at the rear and dequeue from the front. This fundamental difference makes stacks suitable for depth-first traversal and queues for breadth-first traversal.

class QueueTwoStacks:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []
    # enqueue: O(1) amortized
    def enqueue(self, item):
        self.in_stack.append(item)
    # dequeue: O(1) amortized
    def dequeue(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        if not self.out_stack:
            raise IndexError("dequeue from empty queue")
        return self.out_stack.pop()

